	private class TimelineAction : DockingAction {
		private BreakType breakType;
		private SearchType searchType;
		private PluginTool tool;

		private TimelineAction(PluginTool tool, SearchType searchType, BreakType breakType) : base(searchType.actionName + " " + breakType.menuName,
					this.name)
    {
			this.breakType = breakType;
			this.tool = tool;
			this.searchType = searchType;

			if (searchType != SearchType.ALL) {
				setPopupMenuData(new MenuData(
						new string[] { "Go to...", searchType.menuGroup, breakType.menuName },
						null,
						this.name));
				setHelpLocation(new HelpLocation("BreakpointTimelinePlugin", "goto_actions"));
			}
			else {
				setPopupMenuData(
						new MenuData(new string[] { searchType.menuGroup, breakType.menuName },
								null, this.name));
				setHelpLocation(new HelpLocation("BreakpointTimelinePlugin", "show_all_actions"));
			}
		}

		/* @Override */
		public void actionPerformed(ActionContext context) {
			AddressSet addrRange = getAddessRangeFromContext(context);
			Lifespan lifespan = getLifespan();
			Trace currentTrace =
					tool.getService(typeof(DebuggerTraceManagerService)).getCurrentTrace();

			if (addrRange == null) {
				return;
			}

			switch (breakType) {
				case EXECUTE: return handleExecutionAction(addrRange, lifespan, currentTrace);
				case READ, WRITE, ACCESS: return handleMemoryAction(addrRange, lifespan, currentTrace);
			}
		}

		private AddressSet getAddessRangeFromContext(ActionContext context) {
			switch (context) {
				case CodeViewerActionContext c: return getAddressRangeFromCodeViewerActionContext(c);
				case DebuggerListingActionContext c: return getAddressRangeFromDebuggerListingActionContext(c);
				case DebuggerRegisterActionContext c: return getAddressRangeFromDebuggerRegisterActionContext(c);
				case ByteViewerActionContext c: return getAddressRangeFromByteViewerActionContext(c);
				default: null;
			};
		}

		private Lifespan getLifespan() {
			long currentSnap =
					tool.getService(typeof(DebuggerTraceManagerService)).getCurrentSnap();
			switch (searchType) {
				case ALL, FINAL, FIRST: return Lifespan.ALL;
				case NEXT: return Lifespan.nowOn(currentSnap + 1);
				case PREVIOUS: return Lifespan.before(currentSnap);
			};
		}

		private void handleExecutionAction(AddressSet addrSet, Lifespan lifespan,
				Trace currentTrace) {
			List<TraceObjectValue> hits = currentTrace.getObjectManager()
					.getRootSchema()
					.getContext()
					.getAllSchemas()
					.stream()
					.filter(e => e.getInterfaces().contains(typeof(TraceStackFrame)))
					.map(s => s.checkAliasedAttribute(TraceStackFrame.KEY_PC))
					.flatMap(e => addrSet.stream()
							.flatMap(addrRange => currentTrace.getObjectManager()
									.getValuesIntersecting(lifespan, addrRange, e)
									.stream()))
					.sorted(Comparator.comparingLong(TraceObjectValue.getMinSnap))
					.toList();

			if (!hits.isEmpty()) {
				if (searchType == SearchType.ALL) {
					new BreakpointTimelineActionProvider(tool,
							"All executions in %s - %s".formatted(addrSet.getMinAddress(),
									addrSet.getMaxAddress()), hits.stream()
							.map(c => new AddressSnap(c.castValue(), c.getMinSnap()))
							.toList());
					return;
				}
				Long snap = (searchType) switch {
					case FINAL, PREVIOUS: return hits.getLast().getMinSnap();
					case FIRST, NEXT: return hits.getFirst().getMinSnap();
					default: null;
				};
				if (snap == null) {
					return;
				}
				tool.getService(typeof(DebuggerTraceManagerService)).activateSnap(snap);
			}
			else if (searchType == SearchType.ALL) {
				Msg.showInfo(this, null, breakType.infoTitle(),
						"There are no executions at this location");
			}
			else {
				Msg.showInfo(this, null, breakType.infoTitle(),
						"There is no %s execution at this location".formatted(
								searchType.name().toLowerCase()));
			}
		}

		private void handleMemoryAction(AddressSet addrSet, Lifespan lifespan,
				Trace currentTrace) {
			List<TraceReference> hits = addrSet.stream()
					.flatMap(addrRange => currentTrace.getReferenceManager()
							.getReferencesToRange(lifespan, addrRange)
							.stream())
					.sorted(Comparator.comparingLong(TraceReference.getStartSnap))
					.toList();

			if (!hits.isEmpty()) {
				if (searchType == SearchType.ALL) {
					new BreakpointTimelineActionProvider(tool,
							"All %s in %s - %s".formatted(breakType.name(),
									addrSet.getMinAddress(),
									addrSet.getMaxAddress()), hits.stream()
							.map(c => new AddressSnap(c.getFromAddress(), c.getStartSnap()))
							.toList());
					return;
				}
				Long snap = (searchType) switch {
					case FINAL, PREVIOUS: return hits.getLast().getStartSnap();
					case FIRST, NEXT: return hits.getFirst().getStartSnap();
					default: null;
				};
				if (snap == null) {
					return;
				}
				tool.getService(typeof(DebuggerTraceManagerService)).activateSnap(snap);
			}
			else if (searchType == SearchType.ALL) {
				Msg.showInfo(this, null, breakType.infoTitle(),
						"There are no %s to this location".formatted(breakType.plural()));
			}
			else {
				Msg.showInfo(this, null, breakType.infoTitle(),
						"There is no %s %s to this location".formatted(
								searchType.name().toLowerCase(),
								breakType.menuName.toLowerCase()));
			}
		}

		private AddressSet getAddressRangeFromCodeViewerActionContext(CodeViewerActionContext c) {
			DebuggerStaticMappingService staticMappingService =
					tool.getService(typeof(DebuggerStaticMappingService));
			AddressSet dynamicSet = new AddressSet();
			List<AddressRange> addressRanges = new();

			if (c.getSelection().isEmpty()) {
				addressRanges.add(new AddressRangeImpl(c.getAddress(), c.getAddress()));
			}
			else {
				c.getSelection().getAddressRanges().forEachRemaining(addressRanges.add);
			}

			foreach (AddressRange range in addressRanges) {
				Map<TraceSpan, Collection<MappedAddressRange>> openMappedViews =
						staticMappingService.getOpenMappedViews(c.getProgram(),
								new AddressSet(range));
				foreach (Map.Entry<TraceSpan, Collection<MappedAddressRange>> entry in openMappedViews.entrySet()) {
					if (entry.getKey().getTrace() != currentTrace) {
						continue;
					}
					foreach (MappedAddressRange addressRange in entry.getValue()) {
						dynamicSet.add(addressRange.getDestinationAddressRange().getMinAddress(),
								addressRange.getDestinationAddressRange().getMaxAddress());
					}
				}
			}

			if (dynamicSet.isEmpty()) {
				Msg.showInfo(null, null, "No mapping",
						"No mapping for %s @ 0x%x".formatted(c.getProgram(),
								c.getAddress().getOffset()));
			}
			return dynamicSet;
		}

		private AddressSet getAddressRangeFromDebuggerListingActionContext(
				DebuggerListingActionContext c) {
			AddressSet dynamicSet = new AddressSet();
			if (c.getSelection().isEmpty()) {
				dynamicSet.add(c.getAddress());
			}
			else {
				foreach (AddressRange range in c.getSelection().getAddressRanges()) {
					dynamicSet.add(range.getMinAddress(), range.getMaxAddress());
				}
			}
			return dynamicSet;
		}

		private AddressSet getAddressRangeFromDebuggerRegisterActionContext(
				DebuggerRegisterActionContext c) {
			AddressSpace addressSpace = tool.getService(typeof(DebuggerTraceManagerService))
					.getCurrentTrace()
					.getProgramView()
					.getAddressFactory()
					.getDefaultAddressSpace();
			long regValue = c.getSelected().getValue().longValue();
			Address addr = addressSpace.getAddress(regValue);
			AddressSet addressSet = new AddressSet();
			addressSet.add(addr);
			return addressSet;
		}

		private AddressSet getAddressRangeFromByteViewerActionContext(ByteViewerActionContext c) {
			AddressSet dynamicSet = new AddressSet();

			foreach (AddressRange range in c.getSelection().getAddressRanges()) {
				dynamicSet.add(range.getMinAddress(), range.getMaxAddress());
			}
			return dynamicSet;
		}

		/* @Override */
		public bool isEnabledForContext(ActionContext context) {
			return ((context is CodeViewerActionContext) ||
					        (context is DebuggerListingActionContext) ||
					        (context is DebuggerRegisterActionContext) ||
					        (context is ByteViewerActionContext));
		}
	}

	private PluginTool tool;
	string name = this.GetType().getSimpleName();
	List<TimelineAction> actions;
	private Trace currentTrace;

	BreakpointTimelineActions(PluginTool tool) {
		this.tool = tool;
		actions = new();
		foreach (SearchType searchType in SearchType.values()) {
			foreach (BreakType breakType in BreakType.values()) {
				TimelineAction action = new TimelineAction(tool, searchType, breakType);
				tool.addAction(action);
			}
		}
	}

	void dispose() {
		foreach (TimelineAction action in actions) {
			tool.removeAction(action);
		}
	}

	public void setTrace(Trace t) {
		currentTrace = t;
	}

	internal class _Anon_MouseAdapter_1 : MouseAdapter
	{

				/* @Override */
				public void mouseClicked(MouseEvent e) {
					if (e.getClickCount() == 2) {
						int row = table.getSelectedRow();
						if (row != -1) {
							tool.getService(typeof(DebuggerTraceManagerService))
									.activateSnap(snaps.get(row).snap());
						}
					}
				}
			
	}

